--local assdraw = require 'mp.assdraw'
--local ov = mp.create_osd_overlay("ass-events")
local logo_data = {logo_phoenix, logo_phoenixnews, logo_star1, logo_star2,logo_starmovies}
local line_prefix = [[{\an9\fscx40\fscy40\alpha&H0C&\bord0}]]
local shown = false
local index = 2
local ov = {}

local function render_logo()
    shown = not shown
    if shown then
        index = index%#logo_data+1
        for i, line in ipairs(logo_data[index]) do
            ov[i] = mp.create_osd_overlay("ass-events")
            ov[i].data = line_prefix .. line
            ov[i]:update()
        end
    else
        for _, v in ipairs(ov) do
            v:remove()
        end
    end
end
mp.add_key_binding("n", "render_logo", render_logo)
